import { IntentBodyContent } from "./intent-body-content"

export const GROUP_A2: Record<string, IntentBodyContent> = {

  employment_contract_hourly_employee: {
    overview: [
      "Hiring hourly employees creates a fundamentally different legal relationship than bringing on salaried workers or independent contractors. An hourly employment contract establishes precise terms around pay rates, scheduling expectations, overtime eligibility, and timekeeping requirements that directly affect your compliance obligations under the Fair Labor Standards Act and comparable state wage laws. Without a written agreement, disputes about pay, hours worked, and job duties become significantly harder to resolve—leaving both employer and employee exposed to misunderstandings that can escalate into formal complaints or litigation.",
      "The core of any hourly employment contract is the wage rate itself, but effective agreements go far beyond listing a dollar-per-hour figure. They define what counts as compensable time—including pre-shift preparation, required training, travel between worksites, and on-call periods—because these determinations directly govern overtime calculations. The contract should also address the workweek definition, pay frequency, and the process for approving and recording overtime hours. Employers in states with daily overtime requirements, split-shift premiums, or mandatory rest breaks must incorporate those provisions explicitly rather than relying on employees to discover them independently.",
      "Overtime eligibility is a critical area where hourly employment contracts must be precise. Non-exempt hourly employees are entitled to one-and-a-half times their regular rate for hours worked beyond forty in a workweek under federal law, with some states imposing stricter thresholds. The employment agreement should confirm non-exempt status explicitly, describe the process for pre-approving overtime, and clarify that unapproved overtime—while subject to discipline—must still be paid when worked. Failing to pay overtime for unauthorized hours is a wage-and-hour violation regardless of your internal policy, and courts have consistently ruled in favor of employees on this point.",
      "Beyond wages, a well-drafted hourly employment contract addresses at-will status or any applicable probationary period, job responsibilities, dress code and conduct expectations, confidentiality of business information, and the circumstances under which termination may occur. Including these elements transforms a bare-minimum wage agreement into a comprehensive document that protects the employer's legitimate interests while giving the employee a clear picture of what the job entails. Both parties benefit when expectations are documented from day one, reducing turnover driven by unmet assumptions and providing a reliable reference point if disputes arise during the employment relationship.",
    ],
    howItWorks: [
      { step: "Define the Pay Rate and Workweek", description: "State the exact hourly rate, the defined workweek start and end day, and pay frequency (weekly, bi-weekly, semi-monthly). Specify whether the rate may vary for different duties—such as a differential for overnight or weekend shifts—and document any applicable state-mandated minimum wage that supersedes the federal floor." },
      { step: "Establish Compensable Time Rules", description: "Describe what hours count as paid work time, including required pre-shift setup, mandatory meetings, job-related training, and travel between locations. Define the timekeeping system the employee must use, the deadline for submitting time records each period, and the consequences for falsification of time entries." },
      { step: "Address Overtime Approval and Calculation", description: "Confirm non-exempt status under the FLSA and applicable state law. State that overtime requires advance supervisor approval but must be paid regardless of whether prior approval was obtained. Describe how the regular rate of pay is calculated when the employee receives bonuses or shift differentials that must be blended into the overtime rate." },
      { step: "Set Scheduling and Attendance Expectations", description: "Outline the anticipated schedule, any flexibility in start and end times, and the process for requesting schedule changes. Address call-out procedures, tardiness policies, and any on-call or standby requirements. If the employer operates in a jurisdiction with predictive scheduling laws, include advance notice provisions and premium pay obligations for last-minute changes." },
      { step: "Include Standard Employment Terms", description: "Add at-will status language or any agreed upon employment period, confidentiality obligations regarding customer data and business information, social media and device use policies, and acknowledgment of the employee handbook. Both parties sign and date the document, with each retaining a copy for their records." },
    ],
    legalConsiderations: [
      { title: "FLSA Non-Exempt Classification", body: "Misclassifying a worker who qualifies as non-exempt under FLSA standards—based on job duties and salary basis tests, not simply the label you give them—exposes you to back pay, liquidated damages equal to the unpaid wages, and attorney fees. Periodically audit hourly roles to confirm classification remains correct as job duties evolve, and review state exemption thresholds which may differ from federal standards." },
      { title: "State Wage Payment Laws", body: "Every state has its own wage payment statute governing minimum wage, overtime thresholds, meal and rest break requirements, and timing of final paychecks upon separation. Hourly contracts must comply with the law of the state where work is performed, not just the state of incorporation. Multi-state employers need separate agreements or carefully drafted choice-of-law provisions reviewed by counsel." },
      { title: "Tip Credits and Tip Pools", body: "Employers in tipped industries must follow strict documentation requirements to claim a tip credit against minimum wage obligations. The employment contract should disclose the tip credit arrangement, the cash wage rate, and the makeup pay obligation when tips plus cash wage fall short of minimum wage. Tip pool arrangements must comply with the FLSA and state rules governing who can participate." },
      { title: "Minor Employee Restrictions", body: "If any hourly employees are minors, federal and state child labor laws restrict permissible hours, shift lengths, and job duties. The employment contract should reference applicable restrictions and obtain required work permits before the minor begins work. Violations carry significant per-incident fines, and some states impose harsher penalties than federal law." },
    ],
    commonMistakes: [
      { mistake: "Rounding Time to the Employee's Disadvantage", fix: "Some rounding practices are legal under FLSA (rounding to the nearest five or fifteen minutes when applied neutrally), but consistently rounding down is a wage theft violation. Use neutral rounding or pay exact minutes worked; document your rounding policy in the employment agreement." },
      { mistake: "Excluding Training and Meeting Time from Hours Worked", fix: "Mandatory training and meetings are compensable time even when scheduled outside normal hours. Voluntary training is not compensable only if it meets all four FLSA criteria. Clearly identify in the contract which activities are required and therefore paid to prevent wage claim exposure." },
      { mistake: "Treating Auto-Deducted Meal Breaks as Absolute", fix: "Auto-deducting thirty minutes for a meal break is unlawful if the employee is not fully relieved of all duties during that time. The contract should require employees to report interrupted breaks and establish a process for correcting missed break pay rather than simply relying on an automatic deduction." },
      { mistake: "Using a Flat Weekly Salary for Fluctuating Schedules", fix: "Paying a flat weekly salary to non-exempt hourly workers is not a lawful workaround for overtime unless the fluctuating workweek method is properly established under FLSA—which requires a clear mutual understanding and additional half-time for overtime hours. Absent proper setup, the employee can claim regular overtime at time-and-a-half." },
      { mistake: "Omitting the Pay Period End Date and Payday", fix: "Employees have a legal right to know when they will be paid. Many states require employers to notify employees of their pay period and payday in writing at the start of employment. Including this information in the contract satisfies the notice requirement and reduces payroll disputes." },
    ],
    extendedFaq: [
      { question: "Can I require my hourly employee to be available on-call without paying them?", answer: "It depends on the nature of the on-call arrangement. If the employee must remain at a specific location or is so restricted that they cannot use the time for personal purposes, that time is compensable. If the employee can freely use on-call time and simply must respond within a reasonable period, it may not be compensable. The employment contract should define on-call expectations clearly, and you should document your on-call pay policy in writing." },
      { question: "Do I need a written employment contract for hourly employees or is a verbal agreement enough?", answer: "Verbal agreements are generally legally enforceable but extremely difficult to prove. A written hourly employment contract is strongly recommended because it creates an unambiguous record of the agreed wage rate, schedule, and policies. Without it, disputes about promised pay rates, overtime approval procedures, or job duties often become he-said-she-said conflicts that cost both parties significant time and money to resolve." },
      { question: "What happens if I change an hourly employee's pay rate after the contract is signed?", answer: "A pay rate change is a material modification to the employment contract. For at-will employees, you can generally change pay prospectively with reasonable advance notice, but the change cannot apply retroactively to hours already worked. Best practice is to provide written notice of the new rate, have the employee acknowledge receipt, and retain the acknowledgment with personnel records. Some states require specific advance notice periods before a pay rate reduction takes effect." },
      { question: "Can my hourly employment contract include a non-compete clause?", answer: "Non-compete enforceability for hourly workers varies significantly by state. Some states—including California, North Dakota, and Oklahoma—prohibit them almost entirely. Others restrict their use to employees with access to trade secrets or confidential information, which hourly workers may lack. Courts apply heightened scrutiny to non-competes for lower-wage hourly workers and are unlikely to enforce broad restrictions that prevent someone from earning a living. Consult an employment attorney before including non-compete language for hourly employees." },
    ],
  },

  employment_contract_salaried_employee: {
    overview: [
      "A salaried employment contract memorializes the terms under which an employer agrees to pay a fixed weekly, bi-weekly, or monthly compensation amount regardless of the number of hours the employee works. This wage structure is the defining feature of salaried employment, but the legal treatment of salaried workers varies dramatically depending on whether they are classified as exempt or non-exempt under the Fair Labor Standards Act and state wage laws. Getting that classification right—and documenting it clearly in the employment contract—is one of the most consequential decisions an employer makes when drafting the agreement.",
      "Exempt salaried employees must meet both the salary basis test and a duties test under federal law. The salary basis test currently requires payment of at least $684 per week ($35,568 annually) without improper deductions. The duties tests cover executive, administrative, professional, computer, and outside sales categories, each with specific criteria about the nature of the work performed. When an employee qualifies for an exemption, they are not entitled to overtime pay regardless of total hours worked—which is why employers sometimes misclassify non-exempt workers as salaried exempt to avoid overtime costs. That misclassification carries severe financial and legal consequences.",
      "Non-exempt salaried employees receive a fixed salary but remain entitled to overtime pay. Under the FLSA's fluctuating workweek method, an employer can pay a fixed salary that covers all hours worked in a week, with only a half-time premium owed for overtime hours, provided certain conditions are met. This arrangement must be genuinely agreed upon by the employee in advance and documented in the employment contract—it cannot be imposed retroactively or applied inconsistently. Many states do not permit the fluctuating workweek method, so salaried non-exempt workers in those jurisdictions must receive a full time-and-a-half premium for overtime hours.",
      "Beyond classification and compensation, a complete salaried employment contract addresses job title and responsibilities, reporting structure, benefits eligibility and summary plan descriptions, paid time off policies, performance review schedules, grounds for termination, and any confidentiality or intellectual property assignment obligations. For senior or specialized roles, the agreement may also include severance provisions, equity participation terms, and post-employment restrictions. Because salaried positions often involve access to sensitive business information, the intellectual property and confidentiality clauses in salaried employment contracts typically carry more legal weight and more detailed drafting than those in hourly agreements.",
    ],
    howItWorks: [
      { step: "Determine and Document Classification", description: "Before drafting the contract, conduct a formal duties analysis to determine whether the role qualifies for an FLSA exemption and any applicable state exemption. Document the basis for your classification decision in writing and retain it. State the classification (exempt or non-exempt) explicitly in the employment agreement along with the weekly salary amount." },
      { step: "Specify the Salary and Pay Schedule", description: "State the annual salary figure, the equivalent weekly or bi-weekly payment amount, and the pay dates. If the salary includes variable components such as a target bonus, describe the bonus structure, eligibility criteria, measurement period, and payment timing. Clarify whether the bonus is discretionary or guaranteed upon meeting defined performance metrics." },
      { step: "Define Job Responsibilities and Reporting Structure", description: "Include a description of the employee's core duties, their title, and the supervisor to whom they report. For exempt employees, the duties description is legally significant because it must align with the applicable exemption category. A vague or inaccurate duties description undermines your exemption defense in a wage-and-hour audit or lawsuit." },
      { step: "Address Benefits and Leave", description: "Summarize health insurance, retirement plan, and other benefit eligibility, referencing the formal plan documents that govern each benefit. State the accrual rate and carryover rules for paid time off, or note that the company uses an unlimited PTO policy. Identify any waiting periods before benefits become effective and what happens to accrued leave upon separation." },
      { step: "Include Intellectual Property and Confidentiality Terms", description: "Require the employee to assign to the employer all work product created in the scope of employment, with limited carve-outs for personal projects that do not use company resources or trade secrets. Include a confidentiality covenant protecting business information during and after employment. Have the employee sign the agreement before or on the first day of work, not after they have started." },
    ],
    legalConsiderations: [
      { title: "Improper Salary Deductions Destroy Exemption", body: "Making deductions from an exempt employee's salary for partial-day absences, disciplinary suspensions of less than one week, or other reasons not permitted by FLSA regulations destroys the salary basis and subjects the employer to overtime liability retroactively for all weeks in which improper deductions occurred. Maintain a clear written policy prohibiting improper deductions and establish a complaint mechanism to catch and correct mistakes quickly." },
      { title: "State Salary Thresholds May Exceed Federal", body: "Several states have salary thresholds for exempt status that are higher than the federal $684-per-week floor. California currently requires $1,040 per week (doubling the state minimum wage) for white-collar exemptions. Employers operating in high-threshold states must meet the state minimum, and if the employee works remotely across state lines, the analysis becomes complex. Always identify the state of performance when setting the salary for an exempt role." },
      { title: "Bonus Impact on Overtime for Non-Exempt Salaried Workers", body: "Non-discretionary bonuses paid to non-exempt salaried employees must be included in the regular rate calculation when computing overtime. This is frequently overlooked by employers who assume that overtime is simply one-and-a-half times the hourly equivalent of the base salary. Bonuses tied to production, attendance, or performance targets are non-discretionary and must be blended into the overtime rate for the relevant pay periods." },
      { title: "Written Offer Letters vs. Employment Contracts", body: "Many employers use offer letters rather than formal employment contracts for salaried employees. While an offer letter can be binding, it often lacks the specificity needed to protect the employer's interests regarding IP assignment, confidentiality, dispute resolution, and post-employment restrictions. A comprehensive employment contract—signed by both parties—provides more reliable legal protection, particularly for senior roles with access to sensitive information." },
    ],
    commonMistakes: [
      { mistake: "Assuming Job Title Determines Exempt Status", fix: "Calling someone a 'manager' or 'director' does not make them exempt. The exemption analysis turns on actual duties performed, not job title. An employee titled 'Assistant Manager' who spends most of their time performing the same tasks as hourly workers is likely non-exempt despite the title. Conduct a real duties analysis before making the classification." },
      { mistake: "Setting Salary Below the Applicable Threshold", fix: "Paying less than $684 per week automatically disqualifies the employee from any white-collar FLSA exemption, regardless of their duties. Audit compensation for all classified-exempt employees annually and adjust for any increases to the federal or state salary threshold. Budget for threshold changes by monitoring proposed regulations." },
      { mistake: "Docking Pay for Partial-Day Absences Without a Paid Leave Policy", fix: "Under the salary basis rule, exempt employees generally cannot have salary docked for partial-day absences unless they have a bona fide PTO/sick leave plan and the deduction is made against that bank. Create and document a formal leave policy that allows partial-day deductions from the leave bank rather than from salary." },
      { mistake: "Omitting a Severance or At-Will Clause", fix: "Without clear language, employees sometimes interpret a long-term employment relationship as an implied promise of continued employment. Including explicit at-will language—or, where appropriate, specifying a fixed term with defined termination triggers—prevents disputes about whether the employer had 'cause' to end the relationship and whether severance is owed." },
      { mistake: "Failing to Address Bonus Recoupment", fix: "If a salaried employee receives an annual bonus and then resigns shortly after payment, the employer may want to recoup a pro-rated portion. Include a clear bonus recoupment clause specifying the conditions and repayment schedule, and ensure it complies with state wage payment laws, which in some jurisdictions limit or prohibit recoupment from final paychecks." },
    ],
    extendedFaq: [
      { question: "Can I convert a salaried exempt employee to hourly without their consent?", answer: "Converting an exempt employee to hourly is a material change to the employment agreement that typically requires advance notice and, for employees with written contracts, may require mutual agreement. In at-will employment relationships, the employer can prospectively change the pay structure with appropriate notice. However, the reclassification may affect the employee's morale and retention, and you must ensure the change does not expose the employee to overtime obligations you are not prepared to pay." },
      { question: "What should my salaried employment contract say about remote work?", answer: "Address the primary work location or confirm that work is remote, the equipment the employer will provide, any reimbursement policy for home office expenses, the state whose laws govern the relationship (particularly important for remote workers in different states than the employer's principal office), and any requirements for the employee to be physically present for meetings or events. State tax and wage law compliance obligations follow the state where the employee performs the work." },
      { question: "Does a salaried employment contract need to include a non-compete clause?", answer: "Non-compete clauses are optional and their enforceability depends entirely on state law. Several states restrict or prohibit non-competes for employees below certain income thresholds or in certain professions. For salaried employees with access to trade secrets, client relationships, or proprietary technology, a carefully drafted non-compete combined with a non-solicitation clause may be warranted—but requires independent consideration and must be narrowly tailored to be enforceable." },
      { question: "How does paid time off interact with an exempt salaried employee's status?", answer: "Exempt employees can have a paid time off policy without affecting their exempt status. The key rule is that if the employer has a bona fide PTO plan, deductions for absences can be made from the PTO bank without destroying the salary basis. If the employee has exhausted PTO and is absent for a full day for personal reasons, a deduction from salary is permissible. But docking salary for partial-day absences not covered by an established leave policy is an improper deduction that risks destroying the exemption." },
    ],
  },

  employment_contract_commission_based: {
    overview: [
      "Commission-based employment agreements govern the relationship between employers and workers whose compensation is substantially or entirely tied to their sales performance rather than a fixed hourly or salary figure. These contracts are most common in industries like real estate, insurance, software sales, financial services, and retail, where individual performance is easily measurable and the employer wants to align employee incentives directly with revenue generation. Drafting a commission-based employment contract requires far greater precision than a standard salary agreement because the entire value of the compensation promise depends on clearly defined terms for earning, calculating, and paying commissions.",
      "The commission structure section is the heart of the agreement and must address several interlocking questions: What triggers a commission—a signed contract, a collected payment, or a shipped product? At what rate is the commission calculated—a flat percentage, a tiered rate that increases with volume, or a differential rate based on product margin? Is the rate the same for all customers or do house accounts, in-house leads, and self-generated leads carry different rates? What happens when a deal is shared between two salespeople—is the commission split equally or allocated by some other method? Without explicit answers to these questions, commission disputes are virtually inevitable.",
      "Draw-against-commission arrangements are a common feature of commission-based employment contracts, particularly for new hires who need income stability while building their pipeline. Under a draw arrangement, the employer advances a fixed amount each pay period that the employee later repays from earned commissions. Recoverable draws must be repaid if commissions fall short; non-recoverable draws are essentially a guaranteed minimum that is not clawed back. The employment contract must clearly state which type of draw applies, the reconciliation schedule, and how deficits are handled at termination. Many states impose restrictions on recouping draw deficits from final paychecks, making the terms of repayment particularly important.",
      "Beyond the commission mechanics, a comprehensive commission-based employment contract addresses base salary (if any), benefits, expense reimbursement, territory definitions, non-solicitation covenants, and what happens to in-progress deals when the employee leaves. The 'tail commission' question—whether an employee is entitled to commissions on deals that close after their termination—generates significant litigation. Some employers pay a trailing commission for a defined period; others cut off commissions at the effective termination date. Whatever the policy, it should be explicit in the employment agreement, because courts in many states will imply a right to earned commissions absent contrary contractual language.",
    ],
    howItWorks: [
      { step: "Define Earned vs. Unearned Commissions", description: "Specify the precise event that causes a commission to 'vest'—most commonly the execution of a binding customer contract, receipt of payment in full, or completion of a delivery milestone. Until that event occurs, the commission is contingent, not earned. This distinction matters for the employee's right to a commission if they resign or are terminated before the trigger event occurs." },
      { step: "Document the Commission Rate Schedule", description: "Attach a rate schedule as an exhibit to the employment agreement. Include base rates, accelerators for exceeding quota, any margin-based adjustments, and different rates for different product lines or customer categories. Specify whether quota periods are monthly, quarterly, or annual, and whether over-quota attainment in one period can offset under-quota performance in another." },
      { step: "Set the Draw Structure and Reconciliation Schedule", description: "If a draw against commission applies, state the draw amount, frequency of payment, whether it is recoverable or non-recoverable, and the reconciliation schedule (monthly, quarterly). Describe what happens if the employee's commission earnings exceed the draw—when is the excess paid?—and what happens if the employee carries a draw deficit into the next period." },
      { step: "Define Territory, Accounts, and Lead Attribution", description: "Specify the geographic territory or named account list the employee is responsible for. Address how leads are assigned, what constitutes a house account, and the process for resolving territory conflicts. Define who owns accounts brought in by the employee versus those assigned by the company, particularly in the context of a post-employment non-solicitation obligation." },
      { step: "Address Post-Employment Commission Rights", description: "State whether the employee is entitled to commissions on deals in the pipeline at termination, and for how long. If a trailing commission period applies, specify its length, the rate, and the conditions (e.g., only for deals where the employee performed the primary sales work). Include a final reconciliation process and the timing of the last commission payment." },
    ],
    legalConsiderations: [
      { title: "Wage Payment Laws Apply to Commissions", body: "Earned commissions are wages under most state wage payment statutes and must be paid with the same regularity as other wages. Withholding earned commissions—whether at mid-employment or upon termination—constitutes a wage violation subject to penalties, interest, and attorney fee awards. Never structure commission plans that create ambiguity about whether a commission is 'earned' before you are ready to pay it." },
      { title: "FLSA Minimum Wage Floor for Commission Workers", body: "Commission-only employees must still receive at least the applicable minimum wage for all hours worked. If in any workweek commissions earned divided by hours worked falls below minimum wage, the employer must make up the difference. Some employers use a commission-only structure to avoid overtime costs; this strategy fails if the employee is non-exempt and earns commissions that, spread across all hours worked, fail the minimum wage test." },
      { title: "Section 7(i) Retail Commission Exemption", body: "The FLSA provides a limited overtime exemption for employees of retail or service establishments who are paid on commission if more than fifty percent of their earnings come from commissions and their regular rate exceeds one-and-a-half times the minimum wage. The employment contract should document the qualifying criteria and track commission-to-total-pay ratios to confirm ongoing eligibility for this exemption each workweek." },
      { title: "State-Specific Commission Payment Laws", body: "California, New York, and several other states have enacted commission payment statutes requiring employers to provide commission employees with a written contract describing the method for calculating and paying commissions and to give a signed copy to the employee. California requires this document to be updated whenever terms change. Failure to comply can expose the employer to penalties beyond the underlying commission dispute." },
    ],
    commonMistakes: [
      { mistake: "Leaving the Commission Trigger Event Undefined", fix: "Vague language like 'commissions are paid on closed deals' invites disputes about when a deal is 'closed.' Specify the exact triggering event—signed order, cleared payment, product delivery, customer acceptance—and whether chargebacks occur if a customer cancels or returns within a defined period." },
      { mistake: "Assuming Resignation Forfeits All Pending Commissions", fix: "Courts in most states will not enforce blanket forfeiture of earned commissions upon voluntary resignation. If a commission vested before resignation—under the contract's own definition of 'earned'—it must be paid. You can define a trailing commission policy that limits post-termination payments, but you cannot retroactively forfeit commissions that already vested under the agreement's own terms." },
      { mistake: "Using Informal Emails or Side Deals to Modify Commission Rates", fix: "Informal modifications to commission rates—through emails, verbal promises, or handshake agreements—create confusion and potential liability. All changes to the commission rate schedule should be made via a signed written amendment to the employment contract or a new rate schedule acknowledged by both parties." },
      { mistake: "Ignoring the Impact of Bonus Payments on Overtime Calculations", fix: "Non-discretionary commissions earned by non-exempt employees must be included in the regular rate for overtime purposes. If a commission is paid quarterly, the employer must retroactively compute additional overtime for weeks in which the employee worked more than forty hours. This recalculation obligation is frequently overlooked and generates significant wage claim exposure." },
      { mistake: "Omitting a Clawback Provision for Canceled Sales", fix: "Without a chargeback or clawback clause, a salesperson who earns a commission on a deal that subsequently cancels retains the commission even though no revenue was generated. Include a clear chargeback window—typically ninety to one hundred eighty days—during which commissions are reversed if the underlying sale cancels or the customer fails to pay." },
    ],
    extendedFaq: [
      { question: "What is the difference between a recoverable and non-recoverable draw?", answer: "A recoverable draw is essentially a loan against future commissions—if the employee's earned commissions fall short of the draw amount in a given period, the deficit must be repaid, either by deduction from future commissions or from a final paycheck. A non-recoverable draw functions as a guaranteed minimum wage floor—if commissions fall short, the employer absorbs the difference and does not pursue repayment. Which type applies must be explicitly stated in the employment contract." },
      { question: "Can my employer change my commission rate without my agreement?", answer: "In most states, an employer can prospectively change commission rates with reasonable advance notice for at-will employees, but the new rate cannot apply retroactively to deals already in progress or commissions already earned. If the commission structure is memorialized in a written employment contract with a fixed term, the employer generally cannot unilaterally modify rates during the term. Any modification should be documented in a signed written amendment." },
      { question: "Do I get a commission if a deal closes after I leave the company?", answer: "Whether you are entitled to post-termination commissions depends on the language of your employment contract. If the contract defines a commission as 'earned' upon customer signing, and the customer signed before your last day, you may be entitled to the commission even if payment from the customer arrives later. If earning requires payment receipt, and you left before the customer paid, you may not be entitled to payment. Trailing commission clauses that pay for a defined period after termination are common and enforceable when clearly drafted." },
      { question: "How should my employer calculate overtime if I am a commission-only salesperson?", answer: "Overtime for commission-only non-exempt salespeople requires blending commission earnings into the regular rate calculation. The total compensation earned in a workweek (commissions plus any draw or bonus) is divided by total hours worked to determine the regular rate. For hours beyond forty, the employer owes an additional half-time premium based on that regular rate. Commission-only pay does not eliminate the overtime obligation for non-exempt workers." },
    ],
  },

  employment_contract_probationary_period: {
    overview: [
      "A probationary period employment contract establishes a defined trial phase at the beginning of the employment relationship during which both employer and employee evaluate whether the match is a good fit. Typically lasting thirty, sixty, or ninety days, probationary periods allow employers to assess new hire performance, culture fit, attendance, and skills before granting full employment status with any associated benefits or protections. For employees, the probationary period provides an opportunity to understand the role's demands and determine whether the position meets their career expectations. Getting the legal language around the probationary period right is critical, because poorly worded provisions can inadvertently create implied employment contracts or expose the employer to discrimination claims.",
      "The most important legal consideration when drafting a probationary period clause is its relationship to at-will employment. Many employers mistakenly believe that labeling a period as 'probationary' gives them broader authority to terminate without cause during that window. In reality, the at-will doctrine already permits termination for any lawful reason—and adding a probationary period can actually create legal risk by implying that employees who complete probation successfully acquire some form of 'permanent' or 'just cause' protection. Courts have found that language like 'upon successful completion of the probationary period, the employee becomes a regular employee' implies that post-probation termination requires cause. Employment attorneys consistently advise that probationary period language include explicit preservation of at-will status throughout the entire employment relationship.",
      "Performance expectations during the probationary period should be documented with specificity. Rather than vague language about 'meeting performance standards,' an effective contract identifies the exact competencies, outputs, or milestones the employee is expected to achieve within the probationary window. This specificity serves two purposes: it gives the employee a clear roadmap for success, and it provides the employer with objective criteria to support a termination decision if the employee falls short. When termination during probation is challenged as discriminatory, documented performance expectations and objective evaluation metrics provide the employer's primary defense.",
      "Benefits eligibility during the probationary period requires careful coordination between the employment contract and the employer's formal benefit plan documents. Many employers delay health insurance enrollment, PTO accrual, and retirement plan participation until probation is complete, but this must be done consistently across similarly situated employees to avoid disparate treatment claims. The employment contract should be clear about which benefits are available during probation, which become available upon successful completion, and what the timeline is for any post-probation enrollment. The contract should also address how accrued but unused benefits are handled if the employee is terminated during the probationary window.",
    ],
    howItWorks: [
      { step: "Define the Probationary Duration and Start Date", description: "State the exact length of the probationary period—typically ninety days—and confirm it begins on the first day of employment. Specify whether the period can be extended if additional evaluation time is needed, and if so, who has authority to extend it and what notice must be given to the employee. Limit extensions to one or two at most to avoid implying indefinite uncertainty." },
      { step: "Document Specific Performance Expectations", description: "List the concrete deliverables, skills, and behavioral standards the employee must demonstrate during the probationary period. For technical roles, include proficiency benchmarks. For customer-facing roles, include attendance, responsiveness, and quality standards. Schedule at least one formal mid-probation check-in where the manager documents performance and communicates any concerns to the employee." },
      { step: "Specify Benefits Eligibility and Timing", description: "Identify which benefits—health insurance, dental, vision, PTO accrual, retirement plan—begin on the first day versus after successful probation completion. Reference the formal plan documents that govern each benefit and confirm that the employment contract does not supersede plan terms. Clarify what happens to any accrued leave if the employee does not complete probation successfully." },
      { step: "Preserve At-Will Status Explicitly", description: "Include clear language stating that the employment relationship is at-will throughout the probationary period and beyond, and that successful completion of probation does not alter at-will status or create any entitlement to continued employment. Have legal counsel review this language carefully to ensure it does not inadvertently imply just-cause protection for post-probation employees." },
      { step: "Establish the Evaluation and Completion Process", description: "Describe the formal process for evaluating performance at the end of probation—written evaluation, manager sign-off, HR review. Specify what 'successful completion' means and whether the employee receives formal notification. If the employer decides not to continue employment after probation, document the decision with reference to the specific expectations that were not met." },
    ],
    legalConsiderations: [
      { title: "Implied Just-Cause Protection Risk", body: "Courts in several states have found that probationary period language implying that post-probation employees become 'permanent' or 'regular' creates an implied covenant of just-cause termination. To avoid this result, draft language that explicitly states at-will status survives probation completion and that the terms 'regular employee' or 'permanent employee' are used solely to denote full benefit eligibility, not employment security." },
      { title: "Discrimination Claims During Probation", body: "Employers are not insulated from discrimination claims simply because a termination occurs during the probationary period. Terminating an employee during probation based on a protected characteristic—race, sex, national origin, disability, religion, age—is unlawful regardless of how early in the employment relationship it occurs. Documenting legitimate, non-discriminatory performance reasons for any probationary termination is essential." },
      { title: "Benefit Plan Waiting Period Coordination", body: "ERISA and the Affordable Care Act impose limits on benefit waiting periods. The ACA prohibits health coverage waiting periods exceeding ninety days for employees who are otherwise eligible. If the probationary period is ninety days, the benefit enrollment date must occur within that window. Coordinate the probationary period length and benefits eligibility date with your benefits administrator to ensure ACA compliance." },
      { title: "Final Paycheck Obligations Upon Probationary Termination", body: "Terminating an employee during the probationary period does not affect the employer's obligation to pay all earned wages and any accrued but vested PTO on the schedule required by state law. Some states require same-day final paycheck upon employer-initiated termination. Failing to meet state final pay requirements generates penalty exposure on top of any wrongful termination claim." },
    ],
    commonMistakes: [
      { mistake: "Using the Word 'Permanent' for Post-Probation Status", fix: "Replace 'permanent employee' with 'regular full-time employee.' The word 'permanent' implies job security and has been used by courts to infer just-cause protection. Update employment contracts, offer letters, and employee handbooks to eliminate 'permanent' as a descriptor for employment status." },
      { mistake: "Failing to Conduct a Mid-Probation Review", fix: "Surprising an employee with a termination at ninety days—with no prior feedback—looks retaliatory and creates discrimination risk. Conduct a formal mid-probation check-in around day forty-five and document performance concerns in writing. This paper trail demonstrates that the termination decision was based on legitimate business reasons, not protected characteristics." },
      { mistake: "Setting a Probationary Period Longer Than Ninety Days", fix: "ACA waiting period rules cap health insurance waiting periods at ninety days for eligible employees. A probationary period that delays health benefits beyond ninety days may violate ACA rules for eligible employees. If additional evaluation time is needed, extend probation while beginning health benefit enrollment on schedule." },
      { mistake: "Treating Probationary Employees as Independent Contractors", fix: "New hires who work on-site under employer direction during a 'trial period' are employees, not independent contractors, regardless of what the employer calls the arrangement. Misclassifying probationary employees as contractors to avoid payroll taxes, benefits, and employment law obligations is a significant legal risk that auditors specifically look for." },
      { mistake: "Not Documenting the Probation Extension Decision", fix: "If you extend probation beyond the original period, notify the employee in writing with a clear explanation of which expectations remain unmet, a revised timeline, and what successful completion will look like. Verbal extensions with no documentation create ambiguity about the employment relationship and weaken the employer's position if termination is subsequently challenged." },
    ],
    extendedFaq: [
      { question: "Does completing a probationary period guarantee continued employment?", answer: "No. Completing a probationary period typically means the employee has met the initial performance benchmarks and becomes eligible for full benefits, but it does not guarantee continued employment in an at-will relationship. The employer retains the right to terminate for any lawful reason at any time, including after probation ends. The employment contract should state this explicitly to prevent the misconception that successful probation creates employment security." },
      { question: "Can an employer extend my probationary period without my consent?", answer: "In an at-will employment relationship, an employer can generally extend a probationary period by notifying the employee in advance, particularly when the extension is documented in the original contract as a possibility. The employee's options are to accept the extension or resign. However, if the original employment contract specified a fixed probationary period with no mention of extensions, a unilateral extension could be challenged as a contract modification. The safest approach is to include extension language in the original agreement." },
      { question: "Am I entitled to unemployment benefits if I am terminated during my probationary period?", answer: "Unemployment eligibility depends on state law and is typically determined by whether the termination was for 'misconduct' rather than on the length of employment or probationary status. In most states, an employee terminated during probation for performance reasons—rather than willful misconduct—will qualify for unemployment benefits if they meet the state's minimum wage and earnings requirements. Probationary termination does not automatically disqualify an employee from unemployment." },
      { question: "What performance standards should I expect during a probationary period?", answer: "Reasonable probationary standards are those that a qualified employee could realistically achieve within the probationary timeframe. They should be clearly communicated at the start of employment in writing, measurable rather than purely subjective, and consistently applied to all employees in similar roles. Standards that are impossible to meet within the probationary window, or that are applied differently to employees in protected classes, can support a discrimination claim even if the underlying performance rationale appears legitimate." },
    ],
  },

  independent_contractor_agreement_project_based: {
    overview: [
      "A project-based independent contractor agreement governs a discrete, defined engagement with a clear scope of work, deliverable set, and end date. Unlike ongoing contractor relationships or employment arrangements, project-based agreements focus on outputs rather than time spent—the contractor is retained to deliver a specific result, and the relationship concludes when that result is achieved. This structure is common in software development, creative production, construction, consulting, and research engagements where the work can be bounded with sufficient specificity to let both parties know when the contract is complete.",
      "The scope of work section is the most important part of any project-based independent contractor agreement. A vague scope is an invitation to scope creep, payment disputes, and classification audits. Effective scope definitions describe the specific deliverables, the acceptance criteria that determine whether each deliverable is complete, any exclusions (work the contractor is explicitly not responsible for), and the assumptions on which the timeline and pricing are based. If the project involves iterative work with revision cycles—common in creative and technology engagements—the agreement should specify the number of revision rounds included and how out-of-scope requests are handled and priced.",
      "Payment structure in project-based contracts typically follows one of three models: a fixed price paid upon completion, a milestone-based payment schedule tied to defined project phases, or a hybrid that combines an upfront deposit with milestone payments and a final balance upon acceptance. The milestone model is generally preferred by both parties because it aligns payment with progress, reduces the contractor's risk of non-payment for completed work, and gives the client a structured opportunity to review and approve progress before the next phase begins. The contract should specify what constitutes completion of each milestone, the client's review period, and the consequences of late payment.",
      "Intellectual property ownership in project-based agreements requires explicit attention because the default legal rules may not align with the parties' expectations. Under copyright law, a work created by an independent contractor is generally owned by the contractor unless it qualifies as a 'work made for hire' under the Copyright Act's narrow definition, or the parties execute a written IP assignment. For most project-based engagements, the client expects to own the final deliverable, but that expectation must be made legally effective through a specific assignment clause. The contractor, in turn, may want to retain the right to display the work in their portfolio—a license-back provision accommodates both interests.",
    ],
    howItWorks: [
      { step: "Define the Project Scope and Deliverables", description: "Attach a detailed Statement of Work as an exhibit listing every deliverable, the format in which each must be provided, the technical or quality standards each must meet, and the number of revision rounds included. Where deliverables depend on client-provided materials or approvals, document those dependencies explicitly and address how delays caused by the client affect the contractor's timeline." },
      { step: "Set the Payment Schedule and Invoicing Process", description: "Specify the total project price, payment milestones, the invoice submission process, and the payment due date after invoice receipt. Include a late payment provision—typically interest accruing at one percent to one-and-a-half percent per month on overdue balances. Address whether the deposit is refundable if the client terminates before project completion, and how much the contractor retains if work in progress is abandoned." },
      { step: "Define the Acceptance and Revision Process", description: "Describe how the client reviews and accepts each deliverable. Specify a review period—commonly five to ten business days—after which silence constitutes acceptance if no written objections are submitted. Define what constitutes a 'revision' versus a 'change order' requiring separate pricing, and describe the change order process including approval requirements and timeline impact." },
      { step: "Assign Intellectual Property Clearly", description: "State that upon receipt of full payment, the contractor assigns all right, title, and interest in the project deliverables to the client. If the contractor uses pre-existing materials, tools, or background IP in the deliverable, carve those out from the assignment and instead grant the client a license to use them as incorporated in the deliverable. Include a portfolio display license if the contractor wishes to showcase the work." },
      { step: "Address Project Completion and Wrap-Up", description: "Define what project completion means, when the contractor's obligations end, and any post-completion support obligation (warranty period, bug fix commitment, training). Specify how outstanding deliverables, passwords, source files, and proprietary client materials are transferred at project close. Include a confirmation of project completion that both parties sign when all deliverables have been accepted." },
    ],
    legalConsiderations: [
      { title: "Worker Classification Risk in Project Engagements", body: "Labeling an engagement 'project-based' does not prevent a worker from being reclassified as an employee. If the client controls the manner and means of the work—not just the end result—dictates the work schedule, or provides all tools and equipment, classification risk increases. Use the ABC test or common law right-to-control test applicable in your state to evaluate the relationship before contracting." },
      { title: "Work for Hire Doctrine Limitations", body: "Only nine categories of work qualify as 'work made for hire' when created by an independent contractor under the Copyright Act. Software, websites, and marketing materials generally do not fall within those categories. Unless a written IP assignment accompanies the work-for-hire clause, the contractor retains copyright even after payment. Ensure the agreement includes both a work-for-hire designation and an unconditional IP assignment as a belt-and-suspenders approach." },
      { title: "Change Order Discipline", body: "Scope creep is the most common source of project-based contract disputes. Without a formal written change order process, clients request additional features and contractors provide them without additional compensation, then dispute the final invoice. A change order clause requiring written client approval before any work outside the original scope begins prevents these disputes and documents the parties' agreement to expand the project." },
      { title: "Termination for Convenience and Kill Fee", body: "Clients may want the right to terminate a project before completion, particularly in long-duration engagements. The agreement should address what happens to work in progress—whether the client receives the work produced to date, what the contractor retains, and whether a kill fee applies for unexpected project cancellation. Without a termination provision, disputes about partial payment for incomplete projects are common." },
    ],
    commonMistakes: [
      { mistake: "Describing Deliverables in Output Terms Only", fix: "Saying 'a completed website' or 'a marketing plan' does not define a deliverable. Specify page count, feature set, file formats, content inclusion, and technical standards. Attach functional specifications or creative briefs as exhibits so acceptance criteria are objective rather than aesthetic or subjective." },
      { mistake: "Not Specifying Who Provides What", fix: "If the client must provide brand assets, content, access credentials, or approvals for the contractor to proceed, document those dependencies. State that delays caused by client-side failures extend the contractor's timeline proportionally. This protects the contractor from breach claims when project delays are actually caused by the client's failure to deliver required inputs." },
      { mistake: "Allowing Unlimited Revisions", fix: "Unlimited revision clauses trap contractors in endless cycles of client feedback. Specify the number of revision rounds included in the project price—typically two or three—and describe the change order process for additional revisions. Define what constitutes a revision (a change to agreed-upon work) versus a rework (a change to deliverables already accepted by the client)." },
      { mistake: "Paying the Full Project Price on Completion Only", fix: "Paying nothing until final delivery creates cash flow problems for the contractor and leverage for clients who delay acceptance to avoid final payment. Structure payments as a deposit plus milestones to distribute payment risk. A thirty percent deposit, forty percent at midpoint deliverables, and thirty percent on final acceptance is a common project-based payment structure." },
      { mistake: "Omitting a Governing Law and Dispute Resolution Clause", fix: "Without a governing law clause, a dispute about which state's law applies can be as expensive as the underlying dispute. Specify the governing state and designate a dispute resolution mechanism—negotiation, mediation, then arbitration, or litigation in a specific venue. For smaller project values, mandatory arbitration is often more efficient than court proceedings." },
    ],
    extendedFaq: [
      { question: "What happens if the client refuses to accept a deliverable I believe is complete?", answer: "The contract should specify what constitutes acceptance and require any objections to be submitted in writing within a defined review period. If the client withholds acceptance without articulating specific, objective deficiencies, they may be in breach of the agreement. The key is having measurable acceptance criteria in the original contract—if deliverables must meet defined technical standards, acceptance cannot be withheld based on subjective dissatisfaction unless the agreement explicitly permits it." },
      { question: "Can I use third-party libraries or open-source code in my project deliverables?", answer: "Yes, but you must disclose any third-party components incorporated into the deliverable, particularly open-source code subject to licensing restrictions. Some open-source licenses (copyleft or 'viral' licenses like GPL) require derivative works to be released under the same license, which may conflict with the client's expectation of proprietary ownership. Disclose all third-party components in the Statement of Work and represent in the agreement that their use does not infringe third-party rights or violate license terms." },
      { question: "What is a discovery or scoping phase, and should it be a separate contract?", answer: "A discovery phase is a preliminary engagement to define the scope, requirements, and specifications before committing to a full project contract. It typically results in a scoping document that becomes the basis for the project contract's Statement of Work. Using a separate, smaller discovery agreement for this phase is best practice because it limits both parties' commitment while the full project scope is still uncertain. The discovery agreement should specify that its deliverable is the scoping document and that a separate contract is required for actual project work." },
      { question: "If I complete 80% of a project and the client terminates, what am I owed?", answer: "The answer depends on your contract's termination provision. If the contract is silent, you may be entitled to quantum meruit—reasonable compensation for the value of work performed. If the contract includes a termination for convenience clause with a kill fee, you are entitled to whatever that clause specifies, plus the value of accepted milestones. Best practice is to negotiate a clear termination formula that compensates the contractor for all completed milestone work plus a percentage of the remaining project value as a kill fee for unexpected termination." },
    ],
  },

  independent_contractor_agreement_ongoing: {
    overview: [
      "An ongoing independent contractor agreement governs a continuing service relationship without a fixed end date, unlike project-based arrangements that terminate upon deliverable completion. These agreements are common when a business needs recurring support from a specialist—a bookkeeper who reconciles accounts monthly, a content writer who produces weekly articles, a social media manager who handles daily posting, or a technology consultant on retainer for system support. The indefinite nature of an ongoing engagement makes careful drafting even more important because both the contractor's classification risk and the potential scope of confidentiality and non-solicitation obligations grow with the duration of the relationship.",
      "Retainer and recurring service arrangements present heightened worker classification risk precisely because of their ongoing nature. Tax authorities and labor agencies look at the totality of the relationship when assessing whether a worker is truly independent, and long-term exclusivity, integration into business operations, and economic dependence on a single client are all factors that point toward employee status. The ongoing independent contractor agreement must affirmatively document the factors supporting contractor status: the contractor's ability to work for other clients, the contractor's control over how tasks are performed, the contractor's provision of their own tools and workspace, and the contractor's responsibility for their own tax obligations.",
      "The scope of services in an ongoing agreement must be defined with enough specificity to identify what the contractor is expected to deliver each month while remaining flexible enough to accommodate the evolving needs of the business. Many ongoing agreements describe a core scope of recurring deliverables—weekly reports, monthly reconciliations, regular campaign performance reviews—supplemented by a mechanism for assigning additional tasks or ad hoc projects at an agreed additional rate. This two-tier structure provides predictability for both parties while allowing the relationship to flex as business needs change without requiring contract renegotiation for every incremental task.",
      "Termination provisions are especially important in ongoing contractor agreements because the open-ended nature of the relationship means neither party has a natural exit point. A well-drafted termination clause gives both parties the right to end the relationship with reasonable advance notice—typically thirty to sixty days—without cause, while also providing for immediate termination in the event of material breach, insolvency, or misconduct. The contract should address what happens to in-progress work, pending invoices, and any retainer balance at termination, and whether the contractor has an obligation to transition work to a successor or provide documentation of ongoing processes.",
    ],
    howItWorks: [
      { step: "Define the Recurring Scope of Services", description: "List the specific deliverables or services the contractor will provide each billing period—monthly, weekly, or on another defined cadence. Specify the format, frequency, and quality standards for each recurring deliverable. Include a process for assigning ad hoc tasks outside the core scope and the hourly or per-task rate that applies to those additional assignments." },
      { step: "Set the Retainer Fee and Invoicing Schedule", description: "State the monthly retainer amount, when invoices are due (typically the first of each month), and when payment is due after invoice receipt (net fifteen or net thirty). Clarify whether the retainer covers a set number of hours or a defined scope, and what happens if the contractor's work in a given period falls short of or exceeds the expected scope. Specify whether unused retainer hours roll over or expire each period." },
      { step: "Define the Review and Feedback Process", description: "Describe how the client communicates task assignments, provides feedback, and approves deliverables during the ongoing engagement. Specify the contractor's turnaround commitment for standard requests and the process for urgent requests that fall outside the normal workflow. Establish a monthly or quarterly review cadence where both parties assess whether the scope and fee remain appropriate." },
      { step: "Address Intellectual Property and Confidentiality", description: "For ongoing relationships, IP assignment and confidentiality obligations must cover all work produced during the entire engagement, not just a single project. Specify that IP assignment applies to every deliverable produced under the agreement and that confidentiality obligations survive termination of the relationship for a defined period—typically two to three years." },
      { step: "Build in a Termination and Transition Process", description: "Give both parties a termination right with thirty to sixty days written notice. During the notice period, require the contractor to continue services and the client to continue paying the retainer. At termination, require the contractor to deliver all work product, documentation, passwords, and client materials and to provide a reasonable transition briefing to the client or their successor." },
    ],
    legalConsiderations: [
      { title: "Exclusivity Provisions Increase Reclassification Risk", body: "Requiring a contractor to work exclusively for you during the engagement—whether explicit or practical due to workload—suggests an employment relationship. Courts and the IRS look at economic dependence and whether the worker has a genuine opportunity to profit from working with other clients. If exclusivity is essential, consult counsel about structuring the relationship and be prepared for heightened scrutiny of the contractor classification." },
      { title: "Equipment and Workspace Ownership", body: "Providing all tools, equipment, software, and workspace to an ongoing contractor is a factor pointing toward employee status. Where possible, require contractors to use their own equipment and software. If client-side access is operationally necessary (e.g., access to client systems), document that the contractor also maintains their own tools for other client engagements to demonstrate independence." },
      { title: "Non-Solicitation Scope in Long-Term Relationships", body: "Ongoing contractor relationships often give contractors exposure to a wide client and employee base. Non-solicitation clauses that prohibit the contractor from soliciting clients or employees for a post-termination period are generally enforceable when narrowly tailored. Courts apply more scrutiny to broad restrictions in contractor agreements than in employment agreements, so limit non-solicitation provisions to clients and employees the contractor actually interacted with during the engagement." },
      { title: "Statute of Limitations for Ongoing Breaches", body: "In a continuing contractual relationship, the question of when the statute of limitations begins to run can be complex. Repeated failures to pay, recurring IP assignment obligations, and continuing confidentiality breaches can each trigger their own limitations period. Include a dispute notice clause requiring parties to raise claims within a defined period of discovering the breach to prevent the accumulation of stale claims against an ongoing relationship." },
    ],
    commonMistakes: [
      { mistake: "Using a Vague 'As Needed' Scope Description", fix: "Agreements that say the contractor will provide services 'as needed' or 'upon request' leave both parties uncertain about what is included in the retainer and what triggers additional billing. List specific recurring deliverables explicitly and use a structured process for assigning additional work." },
      { mistake: "Not Adjusting the Retainer for Scope Changes", fix: "Ongoing relationships naturally evolve, and the original scope often expands without a corresponding retainer adjustment. Build in a quarterly scope review at which both parties can adjust the retainer up or down based on actual work volume. Document any scope or fee adjustments in a signed amendment." },
      { mistake: "Allowing the Relationship to Run Without a Signed Agreement", fix: "Ongoing contractor relationships that begin without a signed agreement—or that continue after the original agreement expires—rely on implied terms and course of dealing for their legal framework. Renew or extend the agreement before it expires, and ensure any substantial relationship has a current, signed contract in place." },
      { mistake: "Omitting a Dispute Escalation Process for Quality Issues", fix: "Without a quality dispute process, a client who is dissatisfied with ongoing deliverables must choose between terminating the relationship or continuing to pay for unsatisfactory work. Include a written notice-and-cure provision that requires the client to notify the contractor of specific quality failures and gives the contractor a defined period to remedy them before termination is available." },
      { mistake: "Not Addressing Subcontracting by the Contractor", fix: "Ongoing contractors sometimes subcontract portions of their work to assistants or subcontractors without the client's knowledge. If the client is paying for a specific individual's expertise, include a clause requiring prior written approval for subcontracting and confirming that the contractor remains responsible for the quality of any subcontracted work." },
    ],
    extendedFaq: [
      { question: "How should I structure a retainer that covers a variable amount of work each month?", answer: "For variable-scope engagements, consider a base retainer covering a defined number of hours or a specified set of recurring deliverables, with an hourly or per-task overage rate for work exceeding that baseline. This structure gives the client cost predictability for routine work while ensuring the contractor is compensated for unusually heavy months. Unused retainer hours can either roll over to the next period or expire, depending on what the parties agree." },
      { question: "What is the difference between an ongoing contractor agreement and an employee relationship?", answer: "The core distinction is control. An employee relationship exists when the hiring party controls not only the result of the work but also the means and methods by which it is performed—including schedule, tools, process, and work location. An independent contractor relationship exists when the hiring party controls only the result and the contractor independently determines how to achieve it. An ongoing agreement that dictates daily hours, requires specific work methods, and prohibits other client relationships looks more like employment than contracting." },
      { question: "Can I terminate an ongoing contractor relationship without notice if the work quality is poor?", answer: "Only if the contract includes an immediate termination right for material breach and the quality failure is significant enough to qualify as material. For minor but persistent quality issues, most contracts require a written notice specifying the deficiency and a cure period during which the contractor has the opportunity to remedy the problem. Terminating without notice or cure for minor quality issues may expose the client to breach of contract claims, particularly if the contractor had already invoiced for completed work." },
      { question: "Does an ongoing contractor agreement automatically renew, and how do I cancel?", answer: "Whether an ongoing agreement auto-renews depends on its terms. Many ongoing agreements continue month-to-month until either party provides written termination notice within the required notice period. Others have an initial term (one year) with automatic monthly renewal thereafter. Review the renewal and termination provisions in your specific agreement and provide termination notice in writing, delivered by the method specified in the agreement (email, certified mail, etc.), to create a clear record of the termination date." },
    ],
  },

  independent_contractor_agreement_designer: {
    overview: [
      "A designer independent contractor agreement addresses the unique legal considerations that arise when retaining a graphic designer, UX/UI designer, brand identity designer, or visual creative on a freelance or project basis. Design work sits at the intersection of creative expression, intellectual property law, and client commercial expectations—making clear contractual terms especially important. Designers frequently leverage pre-existing visual elements, typefaces, stock assets, and stylistic techniques across multiple client projects, while clients typically expect full ownership of custom design work produced for their brand. The designer contractor agreement must navigate these competing interests through precise IP assignment language, asset license documentation, and portfolio rights provisions.",
      "Creative deliverables require a more nuanced acceptance process than technical or quantitative work. A logo redesign or website layout involves aesthetic judgment that can generate subjective disagreement even when the contractor has technically met the brief. The designer contractor agreement should establish a structured feedback and revision process that limits the number of included revision rounds, defines the difference between a revision (a refinement of approved direction) and a concept change (a fundamental shift in creative direction), and requires all feedback to be submitted in consolidated written form rather than delivered verbally over extended meetings. This structure protects the designer from scope creep while giving the client meaningful control over the creative output.",
      "Intellectual property ownership in design engagements is governed by the Copyright Act, which distinguishes between works made by employees (owned by the employer) and works made by independent contractors (owned by the creator unless assigned or falling within the work-made-for-hire category). Custom design work—logos, brand identities, original illustrations—does not fit neatly within the Copyright Act's limited list of contractor works qualifying as 'work made for hire.' This means that unless the designer executes a written IP assignment clause, they legally retain copyright in the deliverables even after being paid. Clients often don't realize this until they try to register the trademark for a logo their agency designed without an assignment clause.",
      "Licensing third-party assets is a significant consideration in designer contracts that non-designers frequently overlook. Stock photography, licensed fonts, icon libraries, and illustration assets are governed by their own license agreements, which may restrict commercial use, prohibit sublicensing, or require attribution. The designer is typically responsible for ensuring that all third-party assets incorporated into client deliverables are properly licensed for the client's intended use. The contract should require the designer to disclose all third-party assets used, provide documentation of applicable licenses, and indemnify the client against claims arising from unauthorized use of third-party materials.",
    ],
    howItWorks: [
      { step: "Define the Creative Brief and Deliverables", description: "Attach a creative brief as an exhibit outlining the design objectives, brand guidelines, target audience, required formats (print, digital, vector, PNG, etc.), and any technical specifications such as color profiles, file resolution, and size requirements. Specify deliverables in both working file formats (AI, PSD, Sketch, Figma) and export formats (PDF, PNG, SVG) so both parties understand what files will be transferred." },
      { step: "Structure the Revision Process", description: "Define the number of revision rounds included in the project price—typically two concept presentations and two revision rounds per accepted concept. Require all revision feedback to be submitted in consolidated written form within a specified review period. Describe the change order process for additional revisions or concept redirects, including the additional hourly or per-round rate that applies." },
      { step: "Address Third-Party Asset Licensing", description: "Require the designer to disclose in writing all third-party fonts, stock assets, icon libraries, and other licensed materials incorporated into deliverables. The disclosure should include the asset name, license type, and the permitted commercial use. If stock assets are licensed at the client's expense, the contract should specify who is responsible for purchasing and maintaining those licenses." },
      { step: "Execute a Complete IP Assignment", description: "State that upon receipt of full payment, the designer assigns all copyright and other intellectual property rights in the custom deliverables to the client. Carve out the designer's pre-existing tools, templates, and design system elements that are incorporated but remain the designer's property, granting the client a license to use those elements only as incorporated into the final deliverable." },
      { step: "Include Portfolio and Attribution Rights", description: "Grant the designer a limited, non-exclusive, royalty-free right to display the work in their portfolio, on their website, and in case study materials for self-promotional purposes. The client may restrict use of sensitive or unreleased materials for a defined embargo period before public portfolio display. Clarify whether attribution (a design credit on the client's website or published materials) is permitted or required." },
    ],
    legalConsiderations: [
      { title: "Copyright Registration Timing", body: "Copyright protection attaches automatically upon creation, but registration with the U.S. Copyright Office is required to file an infringement lawsuit and to claim statutory damages and attorney fees. Registering design works before or within ninety days of publication enables the designer (or client, after IP assignment) to pursue statutory damages of up to $150,000 per willful infringement. The contract should clarify which party is responsible for copyright registration after IP assignment." },
      { title: "Font License Restrictions on Embedding", body: "Many commercial fonts prohibit embedding in documents distributed to third parties or restrict use in logos. Webfonts require separate licensing from desktop licenses. Before incorporating any font into a client deliverable, verify the license permits the client's intended use—particularly logo use, where the font may be rendered as a scalable vector that effectively provides unlimited access to the typeface character shapes." },
      { title: "Moral Rights for Visual Artists", body: "The Visual Artists Rights Act grants creators of 'works of visual art' the right of attribution and the right to prevent intentional modification that would be prejudicial to their honor or reputation. These rights apply to paintings, drawings, prints, sculptures, and certain photographs in limited editions but generally do not apply to commercial graphic design or logos. However, some designers include an attribution right in their contracts to ensure their work is credited when used publicly." },
      { title: "Indemnification for IP Infringement", body: "If a designer uses an unlicensed third-party asset in client work and the asset owner brings an infringement claim, the client may face liability alongside the designer. An indemnification clause in the designer contract shifts this risk to the designer by requiring them to defend and indemnify the client against claims arising from the designer's use of third-party materials. Match the indemnification scope to the designer's insurance coverage to ensure the obligation is economically meaningful." },
    ],
    commonMistakes: [
      { mistake: "Omitting a Working File Delivery Requirement", fix: "Clients who receive only exported PNGs or PDFs cannot modify the design later without recreating it from scratch. Specify in the contract that the designer must deliver all working source files (AI, PSD, Figma, XD, etc.) upon project completion. Some designers charge separately for source files; if so, the contract should make this pricing explicit upfront." },
      { mistake: "Not Defining 'Revision' vs. 'Redesign'", fix: "A revision refines an approved direction; a redesign abandons it. Clients who request fundamental creative changes after seeing initial concepts often argue this is a 'revision' within the included rounds. Define clearly that a change in creative direction constitutes a new concept development, billed separately or as an additional round, not a revision within the original scope." },
      { mistake: "Paying Final Balance Before Receiving Source Files", fix: "Final payment often triggers IP assignment and source file delivery. If the client pays before receiving all files, they lose leverage to ensure delivery. Structure final payment as simultaneous exchange—final files delivered, final payment released—or use an escrow arrangement for larger projects." },
      { mistake: "Using a Generic IP Assignment Without Carving Out Designer Tools", fix: "A blanket IP assignment covering 'all work product' may unintentionally capture the designer's proprietary templates, frameworks, and design system components that existed before the engagement. Carve out pre-existing elements explicitly and describe the limited license granted to the client to use those elements as incorporated into the final deliverable." },
      { mistake: "Failing to Obtain Licensor Approval for Derivative Works", fix: "Using a stock photograph or illustration as the base for a new creative work may require the licensor's permission for derivative use, particularly under restrictive stock licenses. Review all stock asset licenses before building creative work on top of them and confirm in the contract that the designer is responsible for obtaining any necessary permissions." },
    ],
    extendedFaq: [
      { question: "Who owns the logo a designer creates for my business?", answer: "Without a written IP assignment clause, the designer owns the copyright in the logo even after you pay for it. Copyright in works created by independent contractors belongs to the creator by default under U.S. copyright law. To own the logo outright, your contract must include a written assignment of copyright from the designer to your business. This is standard in professional design contracts, but absent explicit language, the designer retains the right to license the design to others." },
      { question: "Can a designer include my company's logo in their portfolio?", answer: "Most designer contracts include a portfolio license allowing the designer to display their work in self-promotional materials. Many clients are comfortable with this, particularly after the project launches publicly. However, clients may reasonably request an embargo period—typically until the brand or product launches publicly—before the designer can display the work. If your project involves sensitive or confidential business information, negotiate the portfolio clause to restrict the designer to showing only the visual design, not underlying business context." },
      { question: "What file formats should I require at project delivery?", answer: "For brand identity work (logos, brand marks), require editable vector source files in AI or EPS format, plus export packages in PNG (transparent background), PDF, and SVG for web use. For print materials, require PDF with embedded fonts and CMYK color mode. For digital/web design, require the working design file (Figma, XD, or Sketch) plus exported assets at standard web resolutions. Specifying required file formats in the contract prevents disputes about what 'final files' means." },
      { question: "What happens if the logo the designer creates is similar to an existing trademark?", answer: "Trademark clearance is the responsibility of the contracting party, not typically the designer (unless clearance services are specifically included in the scope of work). The designer is responsible for originality—not copying existing protected work—but identifying trademark conflicts requires a trademark search that goes beyond what most designers perform. Conduct a trademark search through the USPTO database and hire a trademark attorney to review the proposed mark before finalizing the design and filing for protection." },
    ],
  },

  independent_contractor_agreement_developer: {
    overview: [
      "A developer independent contractor agreement governs the engagement of software engineers, web developers, mobile app developers, and related technical professionals on a freelance or consulting basis. Technology development contracts must address a distinct set of legal issues that do not arise in most service agreements: the nature and scope of intellectual property assignment in code and related technical artifacts, the treatment of open-source dependencies, warranties about code functionality and security, and the handling of proprietary information about systems architecture that the developer necessarily accesses to perform their work. Getting these provisions right is essential for protecting the client's technology investment and the developer's professional interests.",
      "Source code ownership is the central IP concern in developer contracts, and it must be addressed with precision. The client typically expects to own all code written for their project, but this expectation can be undermined by several common oversights. First, the developer may use open-source libraries or frameworks licensed under terms that restrict how the resulting software can be used or distributed—the contract should require disclosure and license-compatibility review. Second, the developer may reuse proprietary modules or components they developed for other clients—the contract must carve these out from the IP assignment and grant a limited license instead. Third, AI-generated code used in the project may carry uncertain copyright status—the contract should address the treatment of AI-assisted outputs.",
      "Warranty and quality provisions in developer contracts directly affect the client's ability to seek recourse for defective code. A professional software development agreement should include a warranty period—typically thirty to ninety days after delivery—during which the developer is obligated to fix bugs in the delivered code that prevent it from conforming to the agreed functional specifications. This warranty should be distinguished from ongoing maintenance (which is a separate paid service) and from issues caused by the client's modifications or third-party software updates. Beyond the warranty period, the developer's liability for defects should be limited by a contractual liability cap, typically equal to the total fees paid under the agreement.",
      "Confidentiality obligations for developers are broader in scope than for most other contractors because access to a client's systems, codebase, database architecture, and technical roadmap gives the developer significant insight into the client's competitive position. The confidentiality clause should cover technical specifications, system architecture, proprietary algorithms, API credentials and access tokens, database schemas, unreleased product roadmaps, and the terms of the engagement itself. Access credentials provided during the engagement must be returned or invalidated at termination, and the developer should be required to certify in writing that all confidential materials have been deleted from personal devices and storage accounts.",
    ],
    howItWorks: [
      { step: "Define the Technical Scope and Functional Requirements", description: "Attach functional specifications, user stories, or a technical requirements document as an exhibit. Define the technology stack, programming languages, frameworks, and any third-party services the implementation must integrate with. Specify the expected performance benchmarks, browser or device compatibility requirements, and security standards the code must meet." },
      { step: "Structure Deliverables and Code Review Milestones", description: "Break the project into development sprints or phases, each with defined deliverables—functional modules, API endpoints, database schemas, test suites. Include a code review or acceptance testing milestone at each phase. Specify the acceptance criteria: does the deliverable must pass automated test cases, meet defined performance thresholds, or pass user acceptance testing by the client?" },
      { step: "Address Open-Source and Third-Party Dependencies", description: "Require the developer to disclose all third-party libraries, frameworks, APIs, and services incorporated into the code, along with their license type (MIT, Apache 2.0, GPL, proprietary). Require the developer to represent that no components with license terms incompatible with the client's commercial use are included without prior written client approval. Maintain a dependency inventory as an exhibit to the agreement." },
      { step: "Execute IP Assignment and Credential Return Obligations", description: "State that upon payment, the developer assigns all intellectual property in custom-written code and related technical documentation to the client. Carve out pre-existing developer tools, frameworks, and libraries from the assignment. At project completion, require the developer to deliver all source code via the agreed repository, revoke personal access to client systems, and certify deletion of confidential materials." },
      { step: "Establish Warranty and Post-Delivery Support Terms", description: "Define a warranty period (thirty to ninety days) during which the developer will fix code defects that prevent conformance with functional specifications at no additional charge. Describe the defect report process, expected response time, and fix turnaround. For ongoing support beyond the warranty period, reference a separate maintenance agreement or specify the hourly rate for post-warranty bug fixes." },
    ],
    legalConsiderations: [
      { title: "Open Source License Compatibility", body: "GPL and AGPL licensed libraries require any software incorporating them to be distributed under the same license terms, effectively requiring open-source distribution of the client's proprietary code. Before incorporating any GPL-licensed dependency into commercial client software, confirm that the use is compatible with the client's intended distribution model. MIT and Apache 2.0 licenses are generally safe for commercial use. The developer contract should require disclosure and approval of any copyleft-licensed dependencies." },
      { title: "Security Vulnerability Disclosure", body: "Developers who discover security vulnerabilities in their own code or in the client's existing systems during an engagement occupy an uncertain legal and ethical position. The contract should establish a responsible disclosure process—requiring the developer to notify the client immediately of any discovered vulnerabilities and to cooperate with remediation efforts without independently disclosing the vulnerability to third parties during the engagement." },
      { title: "AI-Generated Code and Copyright", body: "Code substantially generated by AI tools may not qualify for copyright protection under current law, as copyright requires human authorship. This uncertainty affects the value of the IP assignment if the developer's deliverable is largely AI-generated. The contract should require the developer to represent the percentage of AI-generated versus human-authored code and warrant that they have rights to assign all incorporated code, including AI-assisted portions." },
      { title: "Limitation of Liability for Code Defects", body: "Software defects can cause significant downstream damage—system outages, data loss, security breaches. Without a liability limitation clause, a developer could theoretically face claims far exceeding the project fees. Standard developer contracts limit liability to the total fees paid under the agreement. Clients may push for exceptions to the liability cap for data breaches caused by the developer's negligence; this is a negotiating point to address carefully." },
    ],
    commonMistakes: [
      { mistake: "Vague Acceptance Criteria in Technical Specs", fix: "Acceptance criteria like 'the app must be fast' or 'the code must be clean' are unenforceable. Specify measurable performance requirements—page load under two seconds, ninety-five percent uptime SLA, passing defined automated test suites with a minimum coverage percentage—so acceptance is objective and disputes about whether deliverables are complete can be resolved based on data." },
      { mistake: "Not Requiring Test Coverage as a Deliverable", fix: "Code delivered without automated test coverage is a hidden liability for the client—future modifications may introduce bugs that would have been caught by tests. Require the developer to deliver unit tests with a defined minimum coverage percentage (e.g., eighty percent of business logic functions) as part of the project deliverables." },
      { mistake: "Granting System Access Without a Credential Management Policy", fix: "Developers routinely receive admin credentials, API keys, database access, and deployment permissions during engagements. Without a credential management policy, these access points persist after the engagement ends. Require the developer to document all access provided, return or revoke access within a specified period after project completion, and certify completion of the access revocation process in writing." },
      { mistake: "Using a Flat Fee for Ambiguous Scope", fix: "Technology projects frequently encounter scope changes due to evolving client requirements, integration surprises, or discovery of legacy system constraints. A flat fee for an ambiguous scope almost always results in disputes. Use a phased approach with a change order process, or use time-and-materials pricing with a budget cap for discovery phases before committing to fixed pricing on delivery phases." },
      { mistake: "Not Addressing Ongoing Maintenance After Delivery", fix: "Software requires maintenance—security patches, dependency updates, compatibility fixes for new operating system versions. A developer contract that ends at project delivery leaves the client without a clear path for post-delivery support. Include a post-warranty maintenance option—either a separate retainer agreement or a defined hourly rate for post-delivery support requests." },
    ],
    extendedFaq: [
      { question: "Does my developer own the code they wrote for my app?", answer: "By default under copyright law, an independent contractor owns the code they create unless there is a written agreement assigning copyright to the client. Simply paying for the development does not transfer ownership. Your developer contract must include an explicit IP assignment clause specifying that all custom code, documentation, and related technical materials created for the project are assigned to you upon payment. Without this clause, the developer retains the ability to reuse your code in other projects." },
      { question: "What is a code escrow, and should I require it?", answer: "A code escrow involves depositing the application's source code with a neutral third-party escrow agent who releases it to the client if the developer fails to maintain the software or becomes insolvent. Code escrow is most relevant for enterprise clients who depend on proprietary SaaS software and want assurance that they can access the underlying code if the vendor ceases operations. For smaller projects where the client receives the source code directly, escrow is less necessary, but it is worth considering for any mission-critical application where you rely on the developer's continued availability." },
      { question: "What warranty should I expect from a software developer?", answer: "A standard software development warranty covers functional conformance—the code works as specified in the functional requirements—for a defined period after delivery, typically thirty to ninety days. During the warranty period, the developer is obligated to fix bugs that prevent the code from meeting its specifications at no additional charge. The warranty does not cover feature changes, performance degradation caused by third-party software updates, or issues introduced by the client's modifications to the code after delivery." },
      { question: "How do I protect my proprietary business logic from the developer?", answer: "Protecting proprietary algorithms, business rules, and system architecture from a developer who necessarily accesses them to do their work requires strong contractual protections. The developer contract should include a comprehensive confidentiality clause covering technical specifications, data structures, and proprietary business logic. For particularly sensitive IP, consider compartmentalizing the most sensitive components so that no single developer has visibility into the complete system. After project completion, revoke all access credentials and audit system logs to confirm no residual access remains." },
    ],
  },

  independent_contractor_agreement_marketing: {
    overview: [
      "A marketing independent contractor agreement governs the engagement of freelance marketing professionals—digital marketers, SEO specialists, content strategists, social media managers, paid media buyers, email marketing specialists, and marketing consultants—whose work directly affects the client's brand, reputation, and revenue. Marketing engagements present a distinctive set of contractual challenges because the deliverables are often intangible (strategies, campaigns, brand voice guidelines), the results are influenced by factors outside the contractor's control (market conditions, competition, search algorithm changes), and the contractor's work product includes both original content owned by the client and third-party platform relationships maintained in the contractor's name.",
      "Performance expectations and measurement are a central tension in marketing contracts. Clients naturally want to tie compensation or contract continuation to marketing outcomes—organic traffic growth, conversion rate improvement, social media follower counts, or return on ad spend. Contractors resist pure performance-based arrangements because results depend heavily on factors outside their control: the quality of the client's product, competitive dynamics, platform algorithm changes, and the client's willingness to invest in budget, creative assets, and strategic recommendations. Effective marketing contracts establish objective deliverable standards (number of pieces of content, campaigns launched, A/B tests run) while including optional performance incentives that reward outcomes without making the contractor's base compensation dependent on uncontrollable variables.",
      "Brand voice and content approval are particularly important in marketing contractor agreements because the contractor's work will be published under the client's name and associated with the client's brand. The agreement should establish a content review and approval workflow—who reviews drafts, what the turnaround expectation is, whether the client has final say on all published content, and how disagreements about brand standards are resolved. Without a clear approval process, contractors sometimes publish content without the client's awareness, and clients sometimes withhold payment claiming content they approved but don't like doesn't meet 'quality standards.' Both risks are managed by a structured written approval workflow.",
      "Platform access and account ownership present unique issues in marketing engagements because the contractor often manages accounts and platforms on behalf of the client. Google Ads accounts, Facebook Business Manager access, email service provider accounts, social media profiles, and analytics platforms may be set up in the client's name but managed exclusively by the contractor during the engagement. The marketing contractor agreement should specify that all accounts are created and maintained in the client's name, that the client retains full ownership and access to all platform accounts, and that the contractor's access is revoked at the end of the engagement. Contractors who set up accounts in their own name and resist transferring them at termination create significant legal and operational problems for clients.",
    ],
    howItWorks: [
      { step: "Define the Marketing Scope and Channels", description: "Specify the marketing channels and activities covered by the engagement—SEO, content marketing, paid search, social media management, email marketing, etc. For each channel, define the specific deliverables: number of blog posts per month, weekly social posts, monthly email campaigns, paid campaign management with a defined monthly ad budget. Identify which channels are out of scope to prevent disputes about implied services." },
      { step: "Establish the Content Creation and Approval Workflow", description: "Define the content calendar submission cadence (e.g., submitted two weeks in advance), the client review period (e.g., three business days), and what constitutes approval (explicit sign-off or silence after the review period). Specify who on the client side has authority to approve content and what feedback format is required. Address the contractor's turnaround expectation for implementing revision feedback." },
      { step: "Set Reporting Requirements and KPIs", description: "Specify the reporting cadence—weekly performance snapshots, monthly comprehensive reports—and the metrics to be tracked for each channel (organic traffic, keyword rankings, ad spend and ROAS, email open and click rates, social engagement). Clarify that the contractor reports on metrics but does not guarantee specific outcomes, and that the client is responsible for providing timely access to analytics platforms." },
      { step: "Address Platform Account Ownership and Credentials", description: "Confirm that all advertising accounts, social media profiles, email service provider accounts, and analytics properties are owned by and registered to the client. Require the contractor to use the client's accounts rather than creating their own. At engagement end, require the contractor to remove themselves from all platform accounts and provide a documented list of all platforms accessed during the engagement." },
      { step: "Define IP Ownership for Marketing Assets", description: "Assign ownership of all original content, copy, graphics, ad creative, email templates, and strategic frameworks created during the engagement to the client upon payment. If the contractor uses licensed stock assets, proprietary tools, or third-party analytics software in delivering services, document which assets are assigned versus licensed, and ensure the client has continuing access to necessary licensed assets after the engagement." },
    ],
    legalConsiderations: [
      { title: "FTC Endorsement Guidelines Compliance", body: "Marketing contractors who manage influencer relationships, create sponsored content, or write testimonials on behalf of clients must comply with FTC guidelines requiring clear disclosure of material connections. The contractor's agreement should include a representation that all marketing activities comply with applicable FTC guidelines and that the contractor will implement required disclosures in any content or campaigns that involve compensated endorsements or material connections." },
      { title: "Ad Platform Terms of Service", body: "Google Ads, Meta, LinkedIn, and other platforms impose terms of service that govern permissible advertising practices. Violations—including deceptive ad content, prohibited categories, or policy circumvention—can result in account suspension or banning. The marketing contractor's agreement should require the contractor to ensure all campaigns comply with platform policies and to notify the client immediately of any policy warnings, suspensions, or account issues." },
      { title: "CAN-SPAM and Email Marketing Compliance", body: "Email marketing campaigns must comply with the CAN-SPAM Act and, if targeting EU residents, GDPR. The contractor must ensure that all email campaigns include required unsubscribe mechanisms, are sent only to recipients who have consented to receive email communications, and contain accurate sender identification. The agreement should allocate responsibility for list hygiene—ensuring the client's email lists comply with opt-in requirements—between the contractor and client." },
      { title: "Competitive Client Non-Solicitation", body: "Marketing contractors who manage SEO, paid media, or content strategy for one client often possess detailed knowledge of that client's competitive positioning and keyword strategy. Including a limited non-compete or non-solicitation clause restricting the contractor from providing identical services to direct competitors during the engagement and for a short period after termination protects the client's investment in marketing strategy development without unreasonably restricting the contractor's ability to earn a living." },
    ],
    commonMistakes: [
      { mistake: "Guaranteeing Specific SEO or Traffic Outcomes", fix: "No marketing contractor can guarantee Google rankings, organic traffic levels, or ad performance because these outcomes depend on factors outside anyone's control. If the contract includes performance guarantees that cannot be met due to algorithm changes or competitive factors, the contractor faces breach claims despite performing excellent work. Describe the activities and deliverables you commit to, not the outcomes you hope to achieve." },
      { mistake: "Setting Up Accounts in the Contractor's Name", fix: "Marketing contractors who create Google Ads, Facebook, or other platform accounts in their own name rather than the client's create an enormous transfer problem at engagement end. Always create advertising accounts in the client's name, with the contractor added as an authorized user with manager access. This ensures the client retains ownership and that access revocation at termination is clean and immediate." },
      { mistake: "Publishing Content Without Client Approval", fix: "Publishing content under a client's brand name without written approval—even when the content is high quality—exposes the contractor to liability if the client objects to the content after publication. For content published in real-time (social media), establish a pre-approved content calendar. For longer-form content, require sign-off before publication regardless of time pressure." },
      { mistake: "Treating Ad Spend as Part of Service Fees", fix: "The client's advertising budget (ad spend) should flow directly to the platform from the client's payment method, not through the contractor's accounts. If the contractor pays for ads and invoices the client for reimbursement, the markup, cash flow risk, and platform liability all become contractor problems. Structure the engagement so the client's credit card is directly charged by advertising platforms, with the contractor holding only manager access." },
      { mistake: "Omitting a Clear Process for Budget Changes", fix: "Marketing budgets fluctuate based on business performance, seasonality, and strategic pivots. Without a defined process for adjusting the engagement scope when budgets change, contractors continue performing work that the client can no longer afford, or clients cut budget mid-engagement without adjusting deliverable expectations. Build a formal scope review trigger any time the client's marketing budget changes by more than twenty percent." },
    ],
    extendedFaq: [
      { question: "Who owns the content the marketing contractor creates for my business?", answer: "Under copyright law, content created by an independent contractor is owned by the contractor unless there is a written IP assignment transferring ownership to the client. Your marketing contractor agreement should include an IP assignment clause specifying that all original content, ad creative, email templates, and strategic documents created during the engagement are assigned to you upon payment. This ensures you can continue using the content after the engagement ends without needing the contractor's permission." },
      { question: "Can a marketing contractor work with my direct competitor at the same time?", answer: "Without a non-compete or exclusivity clause, a marketing contractor can legally work with your direct competitors simultaneously. Whether this is acceptable depends on the nature of the engagement. If the contractor is managing your paid search campaigns and your confidential keyword strategy, concurrent competitor work creates a genuine conflict of interest. Negotiate an exclusivity clause for your specific market category, with appropriate compensation for the exclusivity restriction, if concurrent competitor work is a concern." },
      { question: "What should happen to my social media accounts when a contractor engagement ends?", answer: "At engagement end, the contractor should remove themselves from all admin and manager roles on your social media accounts, advertising platforms, email service providers, and analytics tools. You should conduct a post-engagement audit of all platform access and revoke any credentials shared during the engagement. Your marketing contract should require the contractor to maintain and transfer a complete log of all platforms accessed, login credentials created, and accounts set up on your behalf." },
      { question: "How should ad spend budgets be structured in a marketing contract?", answer: "Ad spend should always be separate from the contractor's service fee. The contractor's fee covers their time and expertise; the ad spend is a direct cost that flows to advertising platforms. Require the contractor to manage campaigns through your own advertising accounts, billed directly to your payment method. If the contractor must pay for ads upfront due to account structure constraints, require detailed invoicing with receipts and ensure the arrangement is clearly documented as reimbursement rather than as part of the service fee." },
    ],
  },

  independent_contractor_agreement_construction: {
    overview: [
      "A construction independent contractor agreement governs the engagement of general contractors, subcontractors, specialty tradespeople, and construction management professionals for residential and commercial building projects. Construction contracts carry unique legal dimensions that distinguish them from other service agreements: mechanics lien rights that can cloud property title, bonding and insurance requirements imposed by law and industry practice, complex multi-party relationships between owners, general contractors, and subcontractors, and the application of specific state licensing requirements that render contracts with unlicensed contractors void or voidable. A well-drafted construction contractor agreement manages these risks while establishing clear expectations for scope, timeline, payment, and quality.",
      "The scope of work in a construction contract must balance specificity with the practical reality that construction projects evolve as physical conditions are revealed. Unlike software or marketing deliverables that exist only in digital form, construction work interacts with existing structures, soil conditions, utility locations, and material availability in ways that affect cost and timeline unpredictably. The contract should define the scope with reference to architectural plans, engineering specifications, and material schedules, while including a formal change order process that manages scope evolution without allowing informal verbal changes to become financial disputes. Every change to the original scope—whether owner-initiated or necessitated by unforeseen conditions—should be documented in a signed written change order before the work begins.",
      "Payment structure in construction contracts typically follows a progress payment model, where the owner pays the contractor in installments tied to construction milestones or percentage-complete measurements. This model recognizes that construction work requires significant upfront material purchases and labor costs that the contractor cannot finance indefinitely. Common structures include an initial mobilization payment upon contract execution, followed by monthly progress payments based on the value of work completed during the period, with a final retention amount (typically five to ten percent of the contract value) held back by the owner until substantial completion and lien period expiration. Retainage protects the owner against defects and ensures the contractor completes the punch list.",
      "Mechanics lien laws give contractors and subcontractors the right to place a lien on the property on which they performed work if they are not paid for their services—a significant protection for construction professionals that also creates significant risk for property owners. When a general contractor fails to pay subcontractors, the subcontractors may file liens against the owner's property even though the owner paid the general contractor in full. Construction contracts address this risk through lien waiver requirements, which require contractors and subcontractors to execute conditional or unconditional lien waivers as a condition of receiving each progress payment. Understanding the difference between conditional and unconditional waivers—and using the correct form for each payment stage—is essential for property owners seeking lien protection.",
    ],
    howItWorks: [
      { step: "Define Scope with Reference to Plans and Specifications", description: "Reference the architectural drawings, engineering specifications, and material schedules by drawing number, version, and date in the contract. Include these documents as incorporated exhibits. Specify what work is explicitly excluded from the scope to prevent disputes about implied scope. Define the contractor's responsibility for temporary facilities, site cleanup, permit applications, and inspections." },
      { step: "Establish the Construction Schedule", description: "Include a construction schedule showing major milestones: permit issuance, site mobilization, foundation completion, framing, rough inspections, exterior enclosure, mechanical rough-in, drywall, finishes, and substantial completion. Define substantial completion clearly—typically the point at which the work can be used for its intended purpose despite minor punch list items. Specify consequences for schedule delays, including any per-day liquidated damages provision." },
      { step: "Structure Progress Payments and Retainage", description: "Define the payment application process: the contractor submits a monthly application for payment by a specified date, the owner reviews within a defined window, and payment is released by the payment due date. Specify the retainage percentage, when retainage is released (typically upon substantial completion or lien period expiration), and the application form required (AIA G702/G703 forms are commonly used)." },
      { step: "Document the Change Order Process", description: "Require all scope changes to be documented in a written change order signed by both parties before work begins. The change order must state the scope of the additional work, the price impact (fixed price or time-and-materials), and the schedule impact. Prohibit verbal change authorizations. Specify the contractor's daily labor rates and material markup percentage that apply to time-and-materials change orders." },
      { step: "Address Lien Waivers, Insurance, and Bonding", description: "Require the contractor to submit a conditional lien waiver (waiving lien rights through a specified date conditioned on payment clearing) with each payment application, and an unconditional waiver after payment clears. Specify minimum insurance requirements—general liability, workers' compensation, automobile liability—and require certificates of insurance naming the owner as additional insured before mobilization. For projects above a defined threshold, require a performance and payment bond." },
    ],
    legalConsiderations: [
      { title: "Contractor Licensing Requirements", body: "Most states require general contractors and specialty trade contractors (electrical, plumbing, HVAC, roofing) to hold current state licenses as a condition of performing construction work. Contracts with unlicensed contractors may be void or voidable under state contractor licensing statutes, and in some states, unlicensed contractors cannot collect payment through legal process even for work actually performed. Always verify the contractor's license status before contract execution and include a license number representation in the agreement." },
      { title: "Mechanics Lien Preliminary Notice Requirements", body: "Many states require subcontractors and material suppliers to serve a preliminary notice on the property owner within a specified period of first furnishing labor or materials as a condition of preserving lien rights. The construction contract should acknowledge that subcontractors may serve such notices and establish a preliminary notice tracking process. Failing to require lien waivers from all tiers of the contractor chain leaves the owner vulnerable to lien claims from parties they have never contracted with directly." },
      { title: "Workers' Compensation Classification", body: "Property owners and general contractors may face workers' compensation liability for injuries to subcontractor employees if the subcontractor does not carry its own workers' compensation insurance. Require each subcontractor to provide a current certificate of workers' compensation insurance before beginning work. Some states impose joint employment liability for construction injuries regardless of insurance status; verify your state's specific rules with an insurance broker and construction attorney." },
      { title: "Defect Claims and Statute of Repose", body: "Construction defect claims are subject to two time limits: the ordinary statute of limitations (typically three to ten years from discovery of the defect) and the statute of repose (an absolute cutoff, typically eight to fifteen years from substantial completion). Including an express limited warranty period in the construction contract—one year for workmanship, two years for mechanical systems, ten years for structural defects matching state minimums—establishes the parties' agreed quality standards and creates a framework for resolving defect claims before litigation." },
    ],
    commonMistakes: [
      { mistake: "Relying on a Handshake or Email Thread Instead of a Signed Contract", fix: "Construction projects involve significant money, weeks or months of work, and complex material and labor coordination. Attempting to manage this through emails and verbal agreements virtually guarantees disputes. A signed written contract with clearly defined scope, price, schedule, and change order process is the minimum risk management measure for any project above a trivial scope." },
      { mistake: "Paying Too Much Upfront Without a Performance Bond", fix: "Front-loading payments—paying fifty percent or more upfront before substantial work is complete—eliminates leverage if the contractor abandons the project or performs defective work. Limit the initial mobilization payment to ten to fifteen percent of the contract value, and require a performance bond from the general contractor on projects above a defined threshold to ensure completion if the contractor defaults." },
      { mistake: "Approving Verbal Change Orders", fix: "Every verbal change authorization becomes a dispute about what was authorized and at what price. Require written change orders signed by an authorized owner representative before any out-of-scope work begins. If time pressure genuinely requires starting before paperwork is complete, follow up with a written change order within twenty-four hours and require the contractor to acknowledge it before proceeding further." },
      { mistake: "Not Requiring Subcontractor Lien Waivers", fix: "Getting a lien waiver only from the general contractor does not protect the owner against liens by subcontractors and material suppliers. Require the general contractor to submit conditional lien waivers from all major subcontractors and suppliers with each payment application, demonstrating that the payment is being passed through to the subcontractor tier." },
      { mistake: "Omitting a Dispute Resolution Mechanism", fix: "Construction disputes are common and often involve significant money. Without a dispute resolution clause, parties default to litigation—which is slow, expensive, and disruptive to project completion. Include a tiered dispute resolution clause: first, direct negotiation; second, mediation; third, binding arbitration. Specify the arbitration rules (AAA Construction Industry Rules are widely used) and the venue." },
    ],
    extendedFaq: [
      { question: "What is a lien waiver and why do I need to collect them?", answer: "A lien waiver is a document signed by a contractor, subcontractor, or material supplier waiving their right to file a mechanics lien against your property for work performed or materials supplied up to a specified date. Conditional waivers waive lien rights conditioned on a payment clearing; unconditional waivers are absolute. Collecting conditional waivers with each progress payment and unconditional waivers after each payment clears protects you from lien claims for work you have already paid for—including claims from subcontractors you never directly hired." },
      { question: "How do I verify that a contractor is properly licensed and insured?", answer: "Verify contractor license status through your state's contractor licensing board website—most provide online license lookups by name, license number, and license type. Request a certificate of insurance directly from the contractor's insurance broker (not from the contractor) showing current general liability, workers' compensation, and automobile liability coverage with your project name listed. Verify that the certificate shows you as an additional insured on the general liability policy and that coverage limits meet your contract requirements." },
      { question: "What is the difference between substantial completion and final completion?", answer: "Substantial completion is the point at which the work is sufficiently complete that the owner can use it for its intended purpose, even if minor punch list items remain. Final completion occurs when all punch list items are finished, all required inspections are passed, all close-out documentation (as-builts, warranties, operation manuals) is submitted, and any retainage is released. Substantial completion typically triggers the transfer of occupancy risk, insurance responsibility, and the start of the defect warranty period. Final completion triggers release of retainage and terminates the contractor's active obligations under the agreement." },
      { question: "Can a general contractor use subcontractors without telling me?", answer: "Unless the contract prohibits or restricts subcontracting, a general contractor is generally free to subcontract portions of the work without specific owner approval. However, the general contractor remains fully responsible for subcontractor performance and cannot use subcontracting to avoid liability for defective work. If you want approval rights over subcontractors—particularly for specialty trades or sensitive work—include a clause requiring owner approval before any subcontractor is engaged, along with the right to reject a proposed subcontractor for documented reasonable cause." },
    ],
  },

}
